            scratch[tx] = scratch[tx] + scratch[tx + {stride}]
        T.sync_threads()''' for stride in (lanes>>i for i in range(1,lanes.bit_length())))
    return f'''    if T.call_extern("uint32", "tensor_subgroup_size") >= {lanes}:
{shuffle}
        scratch[tx] = accum
    else:
