    body = ir.stmt_functor.ir_transform(kernel.body, None, rewrite, ["tirx.Evaluate"])
    blocks = {}
    ir.stmt_functor.post_order_visit(body, lambda n: blocks.update({str(n.thread_binding.thread_tag): n})
