                    ((self.webgpu_profile=='decode_fused' and (cfg.heads,cfg.kv_heads,cfg.head_dim)==(16,8,64)) or
                     (self.webgpu_profile=='quant_searched' and (cfg.heads,cfg.kv_heads,cfg.head_dim)==(32,8,64) and QUANT_ATTENTION.get('fused_scores'))))
