    if webgpu_profile not in WEBGPU_PROFILES:raise ValueError('unsupported WebGPU kernel profile')
    def add(kind,**p):
        if provider=='webgpu':p=webgpu_parameters(kind,p,webgpu_profile)
        values[identity(kind,p)]=(kind,p)
