            if self.provider=='webgpu' and r==1:
                add('add_rms',dict(r=r,c=c,eps=cfg.epsilon),hidden,ws['mixed'],other,self.weights[prefix+'ffn_norm.weight'],ws['normal'])
                hidden,other=other,hidden
